const takePendingThrough = `-- name: TakePendingThrough :many
DELETE FROM app.pending_events
WHERE generation = $1 AND aggregate_id = $2 AND event_sequence <= $3
RETURNING event_id, event_sequence, delivery, envelope
`

type TakePendingThroughParams struct {
	Generation      int32
	AggregateID     uuid.UUID
	ThroughSequence int64
}

type TakePendingThroughRow struct {
	EventID       uuid.UUID
	EventSequence int64
	Delivery      string
	Envelope      []byte
}

func (q *Queries) TakePendingThrough(ctx context.Context, arg TakePendingThroughParams) ([]TakePendingThroughRow, error) {
	rows, err := q.db.Query(ctx, takePendingThrough, arg.Generation, arg.AggregateID, arg.ThroughSequence)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TakePendingThroughRow{}
	for rows.Next() {
		var i TakePendingThroughRow
		if err := rows.Scan(
			&i.EventID,
			&i.EventSequence,
			&i.Delivery,
			&i.Envelope,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const touchConsumer = `-- name: TouchConsumer :exec
INSERT INTO app.consumer_status (consumer, broker_seen_at, last_event_at)
VALUES ($1, $2, $3)
ON CONFLICT (consumer) DO UPDATE
SET broker_seen_at = EXCLUDED.broker_seen_at,
    last_event_at = COALESCE(EXCLUDED.last_event_at, app.consumer_status.last_event_at)
`

type TouchConsumerParams struct {
	Consumer     string
	BrokerSeenAt pgtype.Timestamptz
	LastEventAt  pgtype.Timestamptz
}

func (q *Queries) TouchConsumer(ctx context.Context, arg TouchConsumerParams) error {
	_, err := q.db.Exec(ctx, touchConsumer, arg.Consumer, arg.BrokerSeenAt, arg.LastEventAt)
	return err
}

const upsertOffset = `-- name: UpsertOffset :exec
INSERT INTO app.consumer_offsets (consumer, topic, partition, next_offset, high_watermark, updated_at)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (consumer, topic, partition) DO UPDATE
SET next_offset = GREATEST(app.consumer_offsets.next_offset, EXCLUDED.next_offset),
    high_watermark = GREATEST(app.consumer_offsets.high_watermark, EXCLUDED.high_watermark),
    updated_at = EXCLUDED.updated_at
`

type UpsertOffsetParams struct {
	Consumer      string
	Topic         string
	Partition     int32
	NextOffset    int64
	HighWatermark int64
	UpdatedAt     pgtype.Timestamptz
}

func (q *Queries) UpsertOffset(ctx context.Context, arg UpsertOffsetParams) error {
	_, err := q.db.Exec(ctx, upsertOffset,
		arg.Consumer,
		arg.Topic,
		arg.Partition,
		arg.NextOffset,
		arg.HighWatermark,
		arg.UpdatedAt,
	)
	return err
}
